function mcnOwnGuild(id='',allowMember=false){const u=mcnUser(),g=id?mcnGet('guilds',id):mcnDB().guilds.find(g=>g.manager===u.id&&g.status!=='已关闭');demand(g&&g.stationId===u.stationId&&(g.manager===u.id||allowMember&&mcnDB().contracts.some(c=>c.guild===g.id&&c.provider===feProvider()?.id&&['已生效','离会待审'].includes(c.status))),'仅公会管理者或本人签约服务者可查看');return g;}
