function mcnSyncVipShares(){for(const v of db.vipOrders){const s=v.mcnSnapshot,rel=s?.promotion;if(!rel||v.status!=='已支付')continue;const ref=mcnDB().referrals.find(r=>r.id===rel.referral),eligible=ref&&mcnReferralFacts(ref).eligible&&ref.status!=='人工失效',sitePct=v.stationRuleSnapshot?.vipEnabled?v.stationRuleSnapshot.vipPct:0,base=stationSplit(v.amount,sitePct).central,amount=eligible&&v.refundStatus!=='已退款'?uncents(Math.floor(cents(base)*rel.pct/100)):0,key='promotion|vip|'+v.id;let x=mcnDB().shares.find(x=>x.key===key);if(!x){x={id:mcnId('VIPSHARE'),key,kind:'promotion',owner:rel.promoter,stationId:v.stationId,order:v.id,bill:v.id,revenue:'',provider:'',pct:rel.pct,amount:0,paid:0,occupied:0,createdAt:mcnNow(),releaseAt:pd8AddDays(TODAY,s.settlementDays),ruleSnapshot:structuredClone(rel),source:'local',sourceType:'VIP'};mcnDB().shares.push(x);}const delta=addMoney(amount,-x.amount);if(delta){mcnDB().adjustments.push({id:mcnId('ADJ'),share:x.id,stationId:x.stationId,amount:delta,reason:'VIP支付 / 原退款变动',at:mcnNow(),source:'local'});addLedger(x.id,'VIP推广收益原平台留存内划转（模拟）',Math.abs(delta),'VIP平台留存内推广预留','推广应付收益');}Object.assign(x,{base,amount,recoveryDue:Math.max(0,addMoney(x.paid,-amount)),hold:v.refundStatus==='退款处理中'});x.status=x.recoveryDue?'待追回':x.hold?'保全中':amount===0?'待达标':x.paid>=amount?'已结清':x.releaseAt>TODAY?'待结算期':'可结算';if(amount)mcnEvent('收益确认',x.id,x.stationId,v.uid,'share:'+x.id);}}
const mcnV2Before=v2Commit;v2Commit=function(action,id,type,fd){const before=new Set(db.vipOrders.map(v=>v.id)),out=mcnV2Before(action,id,type,fd);for(const v of db.vipOrders){if(before.has(v.id)&&!(action==='v2VipPay'&&v.id===id))continue;if(v.mcnSnapshot)continue;const r=mcnReferral(v.uid),p=r&&mcnDB().promoters.find(p=>p.id===r.promoter&&p.status==='启用');v.mcnSnapshot={version:mcnDB().settings.version,createdDay:TODAY,settlementDays:mcnDB().settings.settlementDays,promotion:mcnDB().settings.promotionEnabled&&r&&p&&r.ruleSnapshot.sourceVip&&!r.forcedExpired&&r.expires>=TODAY&&r.status!=='人工失效'?{promoter:p.id,referral:r.id,pct:mcnLevel(p).pct,kind:p.kind,owner:p.owner}:null};}mcnSyncShares();return out;};
function mcnTag(text,warn=false){return `<span class="mcn-tag ${warn?'warn':''}">${e(text)}</span>`;}
function mcnPanel(title,body,extra=''){return `<section class="mcn-panel"><header><h3>${e(title)}</h3>${extra}</header>${body}</section>`;}
function mcnTable(headers,rows){return `<div class="mcn-table-wrap"><table class="mcn-table"><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">暂无记录；在用户端完成操作后这里同步更新。</td></tr>`}</tbody></table></div>`;}
function mcnBtn(action,label,id='',values={},backend=false,open=false){return `<button type="button" class="${FE.mode==='admin'?'btn small':'fe-btn soft small'}" data-mcn-${open?'open':'command'}="${e(action)}" data-id="${e(id)}" data-values="${e(JSON.stringify(values))}" ${backend?'data-mcn-backend="true"':''}>${e(label)}</button>`;}
function mcnForm(action,id,body,label='保存本地演示',backend=false){return `<form class="mcn-form" data-mcn-form="${e(action)}" data-id="${e(id)}" ${backend?'data-mcn-backend="true"':''}>${body}<div class="mcn-form-error" role="alert"></div><button class="${backend?'btn primary':'fe-btn primary'}" type="submit">${e(label)}</button></form>`;}
function mcnField(name,label,value='',type='text',options=[]){if(type==='select')return feField(name,e(label),value,type,options);if(type==='checkbox')return `<label class="mcn-check"><input type="checkbox" name="${e(name)}" ${value?'checked':''}>${e(label)}</label>`;if(type==='textarea')return feField(name,e(label),value,type);return `<label class="fe-field"><span>${e(label)}</span><input name="${e(name)}" type="${type}" value="${e(value)}" ${type==='number'?'min="0" step="0.01"':''} required></label>`;}
function mcnStats(items){return `<div class="mcn-stats">${items.map(([name,value])=>`<div><small>${e(name)}</small><b>${e(value)}</b></div>`).join('')}</div>`;}
function mcnFrontHeader(name,desc,links=[]){return `<div class="mcn-surface"><section class="mcn-lead"><h1>${e(name)}</h1><p>${e(desc)}</p><div class="mcn-links">${links.map(([page,label])=>feGoBtn(label,page,'','soft small')).join('')}</div></section>`;}
