function mcnShareTable(xs,backend=false){return mcnTable(['收入来源 / 原账单','类型 / 归属','基数 × 比例','应得 / 已付 / 占用','状态 / 可提','处理'],xs.map(x=>[e(x.order)+'<br>'+e(x.bill),e(x.kind==='guild'?'公会 · '+mcnGet('guilds',x.owner).name:'推广 · '+mcnGet('promoters',x.owner).name),money(x.base)+' × '+x.pct+'%',money(x.amount)+' / '+money(x.paid)+' / '+money(x.occupied),mcnTag(x.status,true)+'<br>可提 '+money(mcnAvailable(x))+'<br>结算日 '+e(x.releaseAt),backend?(x.releaseAt>TODAY&&x.amount>0?mcnBtn('releaseShare','演示等待期结束',x.id,{reason:'核对实际履约后推进演示结算期'},true):'')+(x.recoveryDue?mcnBtn('recoverShare','核实追回',x.id,{},true,true):''):e(x.ruleSnapshot.level||x.ruleSnapshot.contract||'原规则快照')]));}
function mcnWithdrawalsTable(xs,backend=false){return mcnTable(['申请 / 原请求','资金类型 / 申请人','金额 / 账户快照','状态','处理'],xs.map(w=>{let actions='';if(backend){if(w.status==='待审核')actions=mcnBtn('withdrawReview','审核',w.id,{},true,true)+mcnBtn('withdrawCancel','驳回',w.id,{reject:true},true,true);if(['待执行','明确失败'].includes(w.status))actions=mcnBtn('withdrawSubmit',w.status==='明确失败'?'明确失败后重试':'提交模拟出款',w.id,{reason:'核对来源和账户后提交模拟出款'},true);if(['在途','结果未知'].includes(w.status))actions=['成功','失败','未知'].map(result=>mcnBtn('withdrawResult','查询原请求：'+result,w.id,{result,reason:'查询同一商业模拟出款请求'},true)).join('');}else if(['待审核','待执行','明确失败'].includes(w.status))actions=mcnBtn('withdrawCancel','撤销申请',w.id);return[e(w.id)+'<br>'+e(w.request||'未提交渠道'),e({guild:'公会分红',promotion:'推广分红',deposit:'保证金退还'}[w.kind])+'<br>'+e(userName(w.user)),money(w.amount)+'<br>'+e(w.payee),mcnTag(w.status,true)+'<br>'+e(w.receipt||''),actions||'留存回执'];}));}
function mcnIncomePage(kind='guild'){const g=kind==='guild'?mcnOwnGuild():null,acc=kind==='promotion'?mcnPromotionAccount():null,p=acc&&mcnPromoter(acc.kind,acc.owner),owner=g?.id||p?.id;demand(owner,'请先启用当前身份的推广资格');const q=mcnEarnings(kind,owner);return mcnFrontHeader(kind==='guild'?'公会收益':'推广收益','来源可追溯到原账单、规则和调整记录；只有可结算金额才能申请出款。',[[kind==='guild'?'mcn':'promotion','返回工作台']])+mcnStats([['已确认应得','D '+q.total],['可结算','D '+q.available],['申请占用','D '+q.occupied],['已到账','D '+q.paid]])+mcnPanel('资金状态',`<p>等待结算 D ${q.pending} · 售后保全 D ${q.held} · 已付待追回 D ${q.recovery}。普通用户与服务者共用同一推广身份；MCN机构使用机构推广身份单独核算。</p>`)+mcnPanel('原来源与分红',mcnShareTable(q.rows))+mcnPanel('结算账户',`<p>${e(g?.payee||p.payee)} · ${g?.payeeVerified||p?.payeeVerified?'已演示核验':mcnDB().settings.payeeRequireVerification?'当前配置需管理员演示核验':'未核验；当前配置不强制'}</p>${mcnBtn('payee','编辑虚构结算账户',g?.id||p.id,{kind:g?'guild':'promotion'},false,true)}`)+mcnPanel('申请收益提款',mcnForm('withdraw',owner,`<input type="hidden" name="kind" value="${kind}">`+mcnField('amount','提款金额（D）',Math.max(mcnDB().settings.withdrawMin,q.available),'number'),'提交提款申请'))+mcnPanel('提款进度',mcnWithdrawalsTable(mcnDB().withdrawals.filter(w=>w.owner===owner&&w.kind===kind)))+'</div>';}
function mcnPromotionPage(){const u=mcnUser(),g=mcnDB().guilds.find(g=>g.manager===u.id&&g.status==='正常');if(MCN.promoKind==='guild'&&!g)MCN.promoKind='user';const acc=mcnPromotionAccount(),p=mcnPromoter(acc.kind,acc.owner),r=mcnDB().settings;let body=mcnFrontHeader('会员推广','普通会员、服务者与MCN都可推广会员；只计算本人直接邀请，不叠加下级推广。',[['mine','我的'],['mcn','公会中心']]);if(g)body+=mcnPanel('推广身份',mcnBtn('chooseKind','个人推广', '',{kind:'user'})+mcnBtn('chooseKind','MCN机构推广','',{kind:'guild'})+`<p>当前：${e(acc.name)}（${acc.kind==='guild'?'机构':'个人'}）</p>`);if(!p)return body+mcnPanel('开启推广',mcnForm('activatePromotion','',mcnField('confirm','我已了解单层直接推广、有效条件、效期与结算规则',false,'checkbox')+`<p>不要求VIP。${mcnPromotionTerms(r)}</p>`,'启用当前身份推广'))+'</div>';const lv=mcnLevel(p),refs=mcnDB().referrals.filter(x=>x.promoter===p.id),q=mcnEarnings('promotion',p.id),url='http://127.0.0.1:8000/?invite='+encodeURIComponent(p.code);body+=mcnStats([['当前推广等级',lv.name],['有效直接会员',refs.filter(r=>r.status==='有效推广').length],['确认推广分红','D '+q.total],['分红比例',lv.pct+'%']])+mcnPanel('邀请码与邀请入口',`<p>当前推广资格：${e(p.status)}</p><code class="mcn-copy">${e(p.code)}</code><code class="mcn-copy">${e(url)}</code><div class="mcn-links">${feGoBtn('预览邀请页面','invite',p.code,'primary small')}${mcnBtn('copyInvite','复制邀请链接',p.code)}${feGoBtn('推广收益与提款','promotionIncome','','soft small')}</div><p>比例作用于原平台扣除分站分成后的留存；不会再从会员实付或服务者净收益加扣。新注册会员归因不可覆盖。</p>`)+mcnPanel('等级与有效条件',mcnTable(['推广等级','有效会员 / 消费门槛','平台留存分红比例'],mcnDB().levels.filter(l=>l.status==='启用').map(l=>[e(l.name),e(l.minMembers+'人 / D '+l.minSpend),e(l.pct+'%')]))+`<p class="mcn-rule-note">${mcnPromotionTerms(r)}生效规则保存到新归因及账单，旧比例不回写。</p>`)+mcnPanel('直接邀请会员',mcnTable(['会员','归因日 / 有效至','有效消费与证据','推广状态'],refs.map(r=>[e(userName(r.user)),e(r.at.slice(0,10)+' / '+r.expires),money(r.spent||0)+'<br>'+e((r.proofs||[]).join('、')||'待实际交易'),mcnTag(r.status,true)+'<br>'+e(r.invalidReason||'')])));return body+'</div>';}
function mcnInvitePage(){mcnEnsure();const code=FE.id||new URLSearchParams(location.search||'').get('invite'),p=mcnDB().promoters.find(p=>p.code===code&&p.status==='启用');if(!p)return mcnFrontHeader('邀请会员','邀请不存在或资格暂停，请向邀请人确认新链接。',[['home','浏览公开服务']])+'</div>';const s=mcnDB().settings;return mcnFrontHeader('一起认识新的陪伴','来自 '+p.name+' 的会员邀请',[['home','先浏览公开服务']])+mcnPanel('邀请说明',`<p>邀请码：${e(p.code)} · 注册站点：${e(siteLabel(p.stationId))}</p><p>注册为普通会员，不强制购买VIP；推广资格与实际收益分别计算。</p><p>当前规则：${mcnPromotionTerms(s)} 已有会员不重新绑定。</p>${mcnBtn('visit','使用此邀请创建新演示会员',p.code)}<p class="mcn-rule-note">该本地链接仅在同一浏览器的演示记录存在时生效。跨设备分享需要未来真实后端。</p>` )+'</div>';}
function mcnBackHeader(routeName){admin19Require();return pageHead(MCN_BACK[routeName],'本地演示 · 公会招募、服务保障和会员推广复用原订单及资金来源。')+`<div class="mcn-surface" data-admin-no-translate><form class="mcn-filter" data-mcn-filter><label>站点范围<select name="site"><option value="">${admin19Require().role==='admin'?'全平台':'本人分站'}</option>${db.stations.filter(s=>mcnScope(s.id)||admin19Require().role==='admin').map(s=>`<option value="${e(s.id)}" ${MCN.site===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select></label><label>记录开始日期<input type="date" name="from" value="${e(MCN.from)}"></label><label>记录结束日期<input type="date" name="to" value="${e(MCN.to)}"></label><label>公会 / 会员 / 编号<input name="q" value="${e(MCN.q)}" placeholder="搜索对象"></label><button class="btn" type="submit">应用范围</button></form>`;}
function mcnFiltered(xs){return xs.filter(x=>(!MCN.from||String(x.at||x.createdAt||'').slice(0,10)>=MCN.from)&&(!MCN.to||String(x.at||x.createdAt||'').slice(0,10)<=MCN.to)&&(!MCN.q||JSON.stringify(x).includes(MCN.q)||x.user&&userName(x.user).includes(MCN.q)||x.guild&&mcnGet('guilds',x.guild).name.includes(MCN.q)));}
function mcnGuildsBack(){const admin=admin19Require().role==='admin',xs=mcnFiltered(mcnRows('guilds'));return mcnBackHeader('mcnGuilds')+mcnPanel('公会机构',mcnTable(['公会 / 站点','用户端管理者','资质与账户','经营 / 保证金','操作'],xs.map(g=>[e(g.name)+'<br>'+e(g.id)+'<br>'+e(siteLabel(g.stationId)),e(userName(g.manager))+'<br>用户端身份',e(g.license)+'<br>'+e(g.payee)+'<br>'+e(g.payeeVerified?'演示已核验':'待核验'),mcnTag(g.status,true)+'<br>余额 '+money(mcnDeposit(g.id).total)+' / 要求 '+money(g.depositRequired)+'<br>'+mcnTag(g.source==='seed'?'虚构示例':'本地申请'),admin?(g.status==='待审核'?mcnBtn('guildReview','审核申请',g.id,{},true,true):['正常','暂停'].includes(g.status)?mcnBtn('guildStatus',g.status==='正常'?'暂停经营':'恢复经营',g.id,{},true,true):'')+(!['退出中','已关闭'].includes(g.status)?mcnBtn('guildPolicy','设置保证金门槛',g.id,{},true,true):'')+(!g.payeeVerified?mcnBtn('verifyPayee','核验结算账户',g.id,{kind:'guild'},true,true):''):'本站查看'])) )+mcnPanel('签约与离会',mcnTable(['服务者 / 公会','状态 / 编号','分红与期限','关系说明','处理'],mcnFiltered(mcnRows('contracts')).map(c=>mcnContractRow(c,admin))))+mcnPanel('联动入口',linkTo('providers','服务者入驻与商品')+' · '+linkTo('agents','原代理商业归属')+' · '+linkTo('mcnDeposits','保证金与保障')+' · '+linkTo('mcnFinance','公会及推广结算'))+'</div>';}
