function mcnDistributionTable(){return mcnTable(['原账单','原服务基数','服务者净额','代理 / 分站','公会 / 推广','总站净留存'],db.revenues.filter(r=>getBy('bills',r.bill)?.mcnSnapshot&&mcnScope(r.stationId)).map(r=>{const guild=mcnShareAmount(r,'guild'),promo=mcnShareAmount(r,'promotion'),site=stationSplit(r.platformAmount,r.stationRuleSnapshot?.serviceEnabled?r.stationRuleSnapshot.servicePct:0);return[e(r.bill),money(r.base),money(addMoney(r.providerAmount,-guild)),money(r.agentAmount)+' / '+money(site.station),money(guild)+' / '+money(promo),money(addMoney(site.central,-promo))];}));}
function mcnFinanceBack(){const admin=admin19Require().role==='admin';mcnSyncShares();return mcnBackHeader('mcnFinance')+mcnPanel('完整资金分配',`<p>各列合计为原账单确认基数；保证金单独核算。原三方表保留毛分配，下面展示其内部公会与推广划转后的净额。</p>`+mcnDistributionTable())+mcnPanel('公会与推广来源明细',mcnShareTable(mcnFiltered(mcnRows('shares')),admin))+mcnPanel('商业提款及保证金退还',mcnWithdrawalsTable(mcnFiltered(mcnRows('withdrawals')),admin))+mcnPanel('原资金模块',linkTo('withdrawalReview','服务者、代理、站长提款审核')+' · '+linkTo('refunds','原订单退款执行')+' · '+linkTo('revenues','原收益分账')+' · '+linkTo('payments','收款对账'))+'</div>';}
function mcnPromotionsBack(){const admin=admin19Require().role==='admin';mcnEvaluateReferrals();return mcnBackHeader('mcnPromotions')+mcnPanel('推广身份',mcnTable(['推广主体','身份 / 站点','当前等级','资格 / 账户','处理'],mcnFiltered(mcnRows('promoters')).map(p=>[e(p.name)+'<br>'+e(p.code),e(p.kind==='guild'?'MCN机构':db.providers.some(x=>x.uid===p.user)?'服务者个人':'普通会员')+'<br>'+e(siteLabel(p.stationId)),e(mcnLevel(p).name),mcnTag(p.status,true)+'<br>'+e(p.payeeVerified?'账户已演示核验':'账户待核验'),admin?mcnBtn('promoterStatus',p.status==='启用'?'暂停推广':'恢复推广',p.id,{},true,true)+(!p.payeeVerified?mcnBtn('verifyPayee','核验账户',p.id,{kind:'promotion'},true,true):''):'仅本站查看'])))+mcnPanel('会员归因及有效条件',mcnTable(['会员 / 推广主体','归因 / 达标截止 / 分红到期','消费与证据','状态 / 原因','核验与处理'],mcnFiltered(mcnRows('referrals')).map(r=>[e(userName(r.user))+'<br>'+e(mcnGet('promoters',r.promoter).name),e(r.at.slice(0,10)+' / '+r.validTo+' / '+r.expires),money(r.spent||0)+'<br>'+e((r.proofs||[]).join('、')||'无确认交易'),mcnTag(r.status,true)+'<br>'+e(r.invalidReason||''),admin?(!getBy('users',r.user)?.mcnVerified?mcnBtn('verifyMember','演示会员核验',r.id,{},true,true):'')+mcnBtn('referralInvalidate','核定无效推广',r.id,{},true,true)+mcnBtn('referralExpire','演示分红效期结束',r.id,{reason:'演示原归因效期已结束，未来新单停止分红'},true):'本站记录'])))+'</div>';}
function mcnSettingsFields(){const s=mcnDB().settings;return `<div class="mcn-grid">${[['depositRequired','新公会最低保证金（D）'],['guildDefaultPct','新签约默认公会比例（%）'],['guildMaxPct','公会比例上限（%）'],['contractDays','默认签约天数（0不限期）'],['coolingDays','离会冷静期（天）'],['claimMax','单案件保障补偿上限（D）'],['withdrawMin','商业提款最低金额（D，0无门槛）'],['settlementDays','完成服务后的结算等待天数'],['bindingDays','归因及分红有效天数（0不限期）'],['validDays','有效推广达标窗口（天，0不限期）'],['minSpend','有效推广确认消费门槛（D）']].map(([k,l])=>mcnField(k,l,s[k],'number')).join('')}</div>${[['payeeRequireVerification','商业提款要求演示账户核验（可关闭）'],['promotionEnabled','开放会员推广'],['requireAdult','有效推广要求成年条件'],['requireVerified','有效推广要求平台演示核验'],['sourceService','已确认服务参与会员推广'],['sourceVip','已支付VIP参与会员推广']].map(([k,l])=>mcnField(k,l,s[k],'checkbox')).join('')}<p class="mcn-rule-note">推广比例基于总站净留存；公会比例基于服务者毛收益。充值、保证金、运费和未确认服务不参与。修改仅影响新归因、新签约、新账单，不回写成交快照。</p>${mcnField('reason','规则调整依据（至少4字）','更新演示经营规则')}`;}
function mcnRulesBack(){admin19Require(true);return mcnBackHeader('mcnRules')+mcnPanel('公会与推广功能设置',mcnForm('settings','',mcnSettingsFields(),'保存规则新版本',true))+mcnPanel('推广等级',mcnTable(['等级','有效会员数 / 消费金额','总站留存提取比例','状态','设置'],mcnDB().levels.map(l=>[e(l.name),e(l.minMembers+' 人 / D '+l.minSpend),l.pct+'%',mcnTag(l.status),mcnBtn('level','编辑等级',l.id,{},true,true)])))+mcnPanel('政策口径',`<p>单层本人直接推广；服务者邀请会员与MCN邀请会员都采用相同条件。站长、代理的既有归属规则仍独立适用。</p><p>参考公会机制：机构审核、签约确认、合约比例、收益记录、保证金和离会核验。金额、比例与期限均为本平台可配置演示参数。</p>`)+'</div>';}
function mcnReportFacts(){const events=mcnFiltered(mcnRows('events')).filter(x=>x.source==='local'),count=t=>events.filter(x=>x.type===t).length,refs=mcnFiltered(mcnRows('referrals')).filter(r=>r.source==='local'),shares=mcnFiltered(mcnRows('shares')).filter(r=>r.source==='local'),adjustments=mcnFiltered(mcnRows('adjustments'));return{events,refs,shares,adjustments,visits:count('邀请访问'),registrations:count('推广注册'),qualified:refs.filter(r=>r.status==='有效推广').length,contracts:count('签约生效'),confirmed:sumMoney(shares,'amount'),paid:sumMoney(mcnFiltered(mcnRows('withdrawals').filter(w=>w.kind!=='deposit'&&w.status==='已到账')),'amount'),compensated:sumMoney(mcnFiltered(mcnRows('claims').filter(c=>c.status==='已赔付')),'approved')};}
function mcnReportsBack(){mcnEvaluateReferrals();mcnSyncShares();const f=mcnReportFacts(),rate=(n,total)=>total?(n/total*100).toFixed(1)+'%':'—（分母0）';return mcnBackHeader('mcnReports')+mcnStats([['公会新签约',f.contracts],['推广新注册',f.registrations],['当前有效推广',f.qualified],['净确认商业分红','D '+f.confirmed]])+mcnPanel('统计口径与分母',`<p>业务时间 UTC：${e(MCN.from||'全部本地记录')} 至 ${e(MCN.to||TODAY)}。只统计当前站点范围、时间范围内实际发生的本地演示事件；预置公会与保证金示例不计入新增经营指标。</p><p>邀请访问 ${f.visits} 次；推广注册 ${f.registrations} 人；有效会员 ${f.qualified} 人。注册转有效率 ${rate(f.qualified,f.refs.length)}（分母：范围内直接归因会员 ${f.refs.length} 人）。访问按点击次数计数，注册按会员唯一编号计数，不将访问次数当独立人数。</p><p>商业提款已到账 D ${f.paid}，服务保障补偿已到账 D ${f.compensated}。保证金缴纳和退还不计营业收入。</p>${mcnBtn('export','导出本地事件CSV','',{},true)}`)+mcnPanel('公会供给与服务质量',mcnTable(['公会','签约 / 待确认','声音与技能','保障案件 / 当前分红'],mcnRows('guilds').map(g=>{const cs=mcnDB().contracts.filter(c=>c.guild===g.id),active=cs.filter(c=>c.status==='已生效'),ps=active.map(c=>getBy('providers',c.provider)),shares=f.shares.filter(x=>x.kind==='guild'&&x.owner===g.id);return[e(g.name)+'<br>'+mcnTag(g.source==='seed'?'预置示例机构':'本地申请'),active.length+' / '+cs.filter(c=>c.status.startsWith('待')).length,e(ps.filter(p=>v22CurrentProfile(p)).length+' / '+ps.length+' 展示资格有效'),e(mcnDB().claims.filter(c=>c.guild===g.id).length+' 件 / D '+sumMoney(shares,'amount'))];})))+mcnPanel('可追溯经营事件',mcnTable(['时间UTC','事件','对象 / 用户','站点 / 来源'],f.events.map(x=>[e(x.at),e(x.type),e(x.object)+'<br>'+e(userName(x.user)),e(siteLabel(x.stationId))+'<br>本地实际演示'])))+mcnPanel('分红调整记录',mcnTable(['时间UTC','分红来源','金额变化','依据'],f.adjustments.map(x=>[e(x.at),e(x.share),money(x.amount),e(x.reason)])))+'</div>';}
function mcnOpenForm(action,id,values={},backend=false){let body='',title='操作确认';const reason=()=>mcnField('reason','操作依据（至少4字）','本地演示业务核对');
 if(action==='sign'){const c=mcnGet('contracts',id);title='确认公会签约';body=`<p>${e(mcnGet('guilds',c.guild).name)} · ${e(providerName(c.provider))}</p><p>提取服务者毛收益 ${c.pct}%；有效期 ${c.from} 至 ${c.to}。只有双方同意才生效，影响后续新账单。</p>`+mcnField('confirm','确认比例、期限及离会冷静期规则',false,'checkbox');}
 else if(action==='amend'){const c=mcnGet('contracts',id);title='提出分红变更';body=mcnField('pct','新的公会提取比例（%）',c.pct,'number')+mcnField('to','新签约截止日',c.to,'date')+'<p>生成待服务者确认的新版本，确认前原签约继续适用。</p>';}
 else if(action==='guildPolicy'){const g=mcnGet('guilds',id);title='设置公会保证金门槛';body=mcnField('depositRequired','本公会最低经营保证金（D，0无门槛）',g.depositRequired,'number')+'<p>调整经营准入，不改变已缴款项、保证金冻结或退款记录。</p>'+reason();}
 else if(action==='guildProfile'){const g=mcnOwnGuild(id);title='公会资料与招募设置';body=mcnField('contact','虚构业务联系人',g.contact)+mcnField('intro','公会介绍',g.intro,'textarea')+mcnField('pct','新邀请的默认公会比例（%）',g.pct,'number');}
 else if(action==='guildResubmit'){title='补充公会材料';body=mcnField('license','新机构材料引用','DEMO-MCN-MATERIAL');}
 else if(action==='guildReview'){title='审核公会申请';body=mcnField('result','审核结论','通过','select',['通过','需补件','驳回'])+reason();}
 else if(action==='claimReview'){const c=mcnGet('claims',id);title='服务保障核定';body=mcnField('result','处理结论','冻结','select',['冻结','驳回'])+mcnField('amount','核定补偿金额（D）',c.amount,'number')+'<p>保障属于核定的额外补偿，原订单退款继续从原售后执行。不得以此重复退原服务款。</p>'+reason();}
 else if(action==='claimApply'){title='申请公会服务保障';body=mcnField('amount','申请额外保障补偿（D）',Math.min(50,mcnDB().settings.claimMax),'number')+reason();}
 else if(action==='payee'){const x=values.kind==='guild'?mcnOwnGuild(id):mcnGet('promoters',id);title='编辑演示结算账户';body=mcnField('payee','虚构账户引用（勿输入真实资料）',x.payee)+`<input type="hidden" name="kind" value="${e(values.kind||'promotion')}"><p>变更后需管理员重新演示核验。已提交提款保留原账户版本。</p>`;}
 else if(action==='level'){const l=mcnGet('levels',id);title='设置推广等级';body=mcnField('name','推广等级名称',l.name)+mcnField('minMembers','最低有效直接会员数',l.minMembers,'number')+mcnField('minSpend','最低有效消费金额（D）',l.minSpend,'number')+mcnField('pct','总站净留存分红比例（%）',l.pct,'number')+mcnField('status','等级状态',l.status,'select',['启用','停用'])+reason();}
 else{const names={leave:'申请离会',guildStatus:'调整公会经营状态',leaveApprove:'审核离会',claimRelease:'解冻结案',guildExit:'申请公会退出',verifyPayee:'核验虚构结算账户',promoterStatus:'调整推广资格',verifyMember:'演示会员身份核验',referralInvalidate:'核定无效推广',withdrawReview:'审核商业提款',withdrawCancel:values.reject?'驳回商业提款':'撤销商业提款',recoverShare:'核实原收益追回'};title=names[action]||title;body=reason();}
 body+=Object.entries(values).map(([key,value])=>`<input type="hidden" name="${e(key)}" value="${e(value===true?'on':String(value))}">`).join('');mcnDialog(title,mcnForm(action,id,body,backend?'确认本地处理':'确认提交',backend));}
function mcnDialog(title,body){mcnCloseDialog();const root=document.createElement('div');root.id='mcn-dialog-root';root.className='mcn-help-dialog';root.innerHTML=`<section role="dialog" aria-modal="true" aria-label="${e(title)}"><header><h2>${e(title)}</h2><div class="mcn-links"><button class="mcn-help-button" data-mcn-help="current">业务 / 字段说明</button><button class="mcn-help-button" data-mcn-close>关闭</button></div></header><div class="mcn-help-body">${body}</div></section>`;document.body.appendChild(root);root.querySelector('input,select,button')?.focus();}
function mcnCloseDialog(){document.getElementById('mcn-dialog-root')?.remove();}
const MCN_HELP={
 mcnGuilds:{purpose:'机构准入、双方签约、离会和经营状态管理。公会管理者使用普通用户端账号；本站站长查看汇总，管理员负责平台审核。',roles:'总站管理员审核；站长查看本站；管理者与服务者在用户端确认各自合作。',flow:'用户端申请 → 平台审核 → 足额保证金 → 邀请 / 申请加入 → 另一方确认 → 新账单保存签约快照 → 冷静期及未完业务核验后离会。',links:['providers','agents','mcnDeposits','mcnFinance','mcnRules','mcnReports'],fields:{'公会':'MCN机构经营主体，和站点、代理分别记录。','管理者':'现有统一用户账号，不创建公会后台账号。','公会比例':'从服务者原三方分账的毛收益内提取；不按会员总实付再次抽成。','签约':'服务者同时只有一个有效公会；比例变更需要服务者再次确认。','状态':'待审核、需补件、待缴保证金、正常、暂停、退出中、已关闭；暂停阻止新招募，不抹去历史。','合约截止':'截止日含当天；过期后不再为新账单保存公会分红。','离会':'冷静期内停止新增分红快照，历史订单继续履约和结算。'}},
 mcnDeposits:{purpose:'核对可退保证金负债、原缴纳请求和订单售后关联的额外服务保障补偿。',roles:'管理者主动缴纳、申请退出；买方在原售后核定后申请保障；管理员冻结、解冻、赔付和审核退还。',flow:'生成缴纳单 → 模拟成功 / 失败 / 未知 → 未知查询原请求 → 原售后先核责 → 保障核定冻结 → 赔付或解冻 → 完结合作后申请剩余保证金退还。',links:['mcnGuilds','stops','refunds','mcnFinance','payments'],fields:{'缴纳累计':'成功回执的入金累计，未支付和结果未知不增加资金。','余额':'缴纳累计减已赔付、已成功退还，属于保证金负债，不是收入。','冻结':'已核定未赔付的保障占用，不能再用于退还。','可用':'余额减案件冻结和退还申请占用。','保障案件':'关联原订单、账单、买方和已执行售后。额外补偿不改写原订单退款数。','退还':'未完合约、履约、售后、未知支付或待追回收益会阻断退出和退还。'}},
 mcnFinance:{purpose:'在原三方、分站分配的内部划分公会和直接会员推广收益，展示净额、保全、占用、追回及原渠道请求。',roles:'用户端按当前可配置账户核验规则申请本人可结算资金；总站管理员审核、执行、查询及核实追回。',flow:'实际确认履约 → 原毛分账 → 公会 / 推广子分配 → 等待结算 → 按配置核验账户 → 申请占用 → 审核 → 提交模拟原请求 → 查询成功、明确失败或未知。',links:['revenues','commissions','stationIncome','withdrawalReview','refunds','payeeAccounts','mcnReports'],fields:{'原基数':'原服务账单已确认履约的净基数，未履约和已核定退款不参与。','服务者净额':'原服务者毛收益扣公会约定分红。','推广基数':'原平台收益扣原分站分成后的总站留存；VIP采用VIP平台留存。','应得':'本来源当前净权益，成功退款会冲减；不把提款当作新收入。','占用':'已申请未结束的提款；未知或在途不能撤销或再提交。','已付待追回':'退款冲减后的应得低于已付时保留原到账，另行核实追回，不当作已自动追回。','结算日':'服务期结束加规则等待天数，后台可明确推进演示等待期。','原请求':'每次提交有唯一模拟请求；失败重试才创建新请求，未知查询原请求。'}},
 mcnPromotions:{purpose:'统一维护普通会员、服务者个人和MCN机构的直接会员邀请、唯一归因、有效条件、期限与资格。',roles:'所有正常成年用户可启用个人推广；正常MCN管理者可启用机构推广；管理员核验、暂停和处理无效关系。',flow:'启用身份 → 邀请页面 → 新会员注册 → 固定直接归因 → 按配置选择是否核验及是否需消费达标 → 有效会员 → 新账单按等级快照分红 → 到期停止新分红。',links:['users','vipOrders','orders','mcnRules','mcnFinance','mcnReports'],fields:{'个人 / 机构':'服务者与普通会员使用同一人的个人推广，MCN机构收益单列，不重复奖励同一注册。','邀请码':'绑定启用的推广身份与本站；不能推广本人、重新绑定旧会员或跨站归因。','达标窗口':'从注册归因日起计算，需要在此窗口内成交并达到实际确认消费门槛。','有效推广':'按原归因快照检查启用的核验与净确认消费条件；门槛0且关闭核验时注册即有效，收入仍需实际来源。','分红到期':'截止日含当天；未来新账单停止，已成交的权益快照继续处理。','比例':'取自新账单创建时的推广等级，基数为总站留存。','人工失效':'管理员依据核查记录停用归因；已确认分红会冲回，已付额形成待追回。'}},
 mcnRules:{purpose:'配置新公会准入与保证金要求、公会分红上限、推广开关、消费类型、有效期限、核验条件、等级和结算等待期。',roles:'仅总站唯一管理员修改全平台规则。',flow:'查看当前版本 → 核对参数与来源 → 填写依据 → 保存新版本 → 新关系和新账单应用 → 历史来源沿原快照。',links:['templates','splitRules','stationRules','mcnGuilds','mcnPromotions','mcnReports'],fields:{'最低保证金':'新公会准入负债资金要求，0可演示不强制缴纳。已有公会保留原要求。','比例上限':'约束后续签约邀请；默认值不可超过上限。','有效消费门槛':'已确认服务净额及允许的已付VIP累计，退款会重新计算。','推广等级':'最低有效直接会员数和消费金额同时达到；达到最高满足等级后用于新账单。','分红有效期':'归因日起的天数；达标窗口不得大于此期。','等待天数':'服务期结束后的资金等待期；与预约周期、VIP期分别计算。','消费类型':'本轮服务和可选VIP；保证金、充值、运费、实物和订阅不计入本轮推广。'}},
 mcnReports:{purpose:'按本站或全平台、时间和本地实际事件追溯机构发展、会员转化、商业收益和保障质量。',roles:'总站管理员看全平台；站长仅本人分站，用户端只看本人团队与直接邀请。',flow:'选择站点及日期 → 查看明示分母 → 核对事件和原来源 → 查看调整记录 → 导出事件CSV。',links:['opsReports','v22Analytics','mcnGuilds','mcnPromotions','mcnFinance','mcnDeposits'],fields:{'新签约':'范围内实际双方确认的签约事件数，未确认邀请不计。','推广注册':'唯一新会员归因事件，以会员ID去重。','有效会员':'范围内归因会员中当前仍达到原规则条件的会员数。','转有效率':'分子有效会员，分母范围内归因会员数，0分母显示空值。','邀请访问':'主动点击邀请进入注册的次数，不冒充独立访客数。','净确认分红':'当前原来源内归集的应得权益；已付、占用和追回另列。','示例数据':'预置公会和保证金标记为虚构示例，不混入本地新增事件漏斗。'}},
 order:{purpose:'核对原订单、周期账单、预约和成交快照，订单双方在这里完成履约、确认和售后。',flow:'选择服务 → 核对价格和档期 → 主动模拟支付 → 服务者提交履约 → 买方确认或提出异议 → 按原快照结算。',links:['orders','stops','revenues','mcnFinance','refunds'],fields:{'实付':'原成功支付金额；待支付不算实付。','已确认':'买方确认或原裁决保留的履约基数。','公会快照':'成交时有效签约及比例，后来退会不改写旧账单。','推广快照':'成交时直接归因、等级和比例，后来等级变化不回写。','剩余权益':'原模板内未履约、未退款的次数或期间。'}},
 finance:{purpose:'核对原支付、收益、提款、退款与清算记录，区分资金流与营业收入。',flow:'关联原业务来源 → 资格与账户核验 → 申请及审核 → 模拟提交 → 查询原请求 → 收到明确结果后记账。',links:['payments','revenues','withdrawalReview','refunds','mcnFinance','mcnDeposits'],fields:{'状态':'待审核、待执行、在途、未知、明确失败和已到账分别处理。','金额':'按原来源、币种和快照，不把多个业务资金种类直接当收入相加。','分红':'公会与推广为原毛收益内划转；查看商业结算确认净额。','保证金':'可退负债，缴纳和退还不算营业收入。','回执':'已成功回执不得重复处理，未知必须先查原请求。'}},
 service:{purpose:'管理用户、服务者资质、商品、技能、声音、档期和公开展示，区分资料审核与交易履约。',flow:'本人提交资料或商品 → 平台审核 → 公开展示 → 用户选择预约 → 按订单履约 → 反馈及复购。',links:['users','providers','applications','skills','products','availability','mcnGuilds','v22Quality'],fields:{'认证':'技能 / 材料审核通过且在有效期才允许新增服务。','状态':'在线、忙碌、离线和暂停接单分别记录；历史已付服务继续处理。','价格':'当前新购价格；已成交金额保留原快照。','公会 / 代理':'合作和商业归属分别存储，不互相覆盖。','声音版本':'替换材料在审核通过前保留原展示版本。'}},
 site:{purpose:'管理分站、站长与代理的现有归属和经营协助；公会作为独立机构接入本站供给。',flow:'建立分站归属 → 授权本站记录 → 服务、订单与商业分成保存站点快照 → 本站汇总及结算。',links:['stations','stationOwners','agents','bindings','stationIncome','mcnGuilds','mcnReports'],fields:{'归属站点':'每条记录保存本站ID，禁止通过界面切换获取跨站操作。','站长':'独立后台登录，仅本人负责分站；公会管理者仍在用户端。','代理':'原团队归属和佣金保留，新增MCN合作不替代代理。','平台留存':'原平台毛收益扣除分站分成，推广在其剩余部分提取。'}},
 social:{purpose:'进行咨询、匹配、社区、语音房或活动的本地互动，与原服务预约和订单关联。',flow:'浏览公开信息 → 检查有效VIP与本站、拉黑关系 → 发起互动 → 可进入预约 → 已付订单按原入口继续处理。',links:['v22Ops','v22Social','v22Activities','reports','orders','mcnGuilds'],fields:{'VIP':'新增社交互动要求有效VIP；公会经营和会员推广工具另按其身份规则。','模拟':'消息、人数、匹配与声音状态为本地演示。','举报':'关联原对象及原案件，管理者不批量阅读私聊。','状态':'房间关闭、匹配超时或咨询结束后禁止新增对应互动。'}},
 config:{purpose:'核对当前功能配置、权限、规则版本、审计与发布状态，保证后续新业务使用正确规则。',flow:'查看适用范围 → 修改草稿或配置 → 按本页面按钮保存 / 发布 → 记录版本和依据 → 从关联模块验证结果。',links:['settings','templates','splitRules','admin19Account','audit','mcnRules'],fields:{'版本':'明确规则生效版本，既有订单继续使用保存的快照。','账号权限':'总站、本站站长和用户端身份分开判定，菜单不是授权。','记录':'处理依据、操作人、对象与时间用于追溯。'}},
 report:{purpose:'按当前界面的业务口径、站点与日期核对经营汇总，并从实际记录追溯统计值。',flow:'选择范围 → 查看指标及分母 → 点击来源记录 → 核对退款 / 结算调整 → 导出当前演示数据。',links:['opsReports','v22Analytics','mcnReports','revenues','orders'],fields:{'统计范围':'使用当前过滤条件，业务时间和真实登录会话时间分别说明。','分母':'人数、订单数与事件次数不是同一口径，按页面明示计算。','示例':'虚构预置数据与本地实际新增分别标识。'}},
 mine:{purpose:'同一账号使用购买、认证服务者、代理及MCN管理者工具，查看自己的记录和收益。',flow:'登录演示账号 → 选择所需身份入口 → 查看本人订单、签约、收益或邀请 → 提交操作 → 到关联后台核验结果。',links:[],fields:{'用户身份':'普通用户能直接购买服务；有效VIP解锁社交。','服务者':'入驻与技能审核通过后出现服务者中心。','MCN':'按当前可配置准入规则创建后，当前用户端账号管理公会。','推广':'普通会员、服务者和机构均可直接推广会员；个人与机构账目区分。'}},
 auth:{purpose:'通过本地模拟注册和登录进入当前浏览器的账号；邀请注册记录唯一直接推广归因。',flow:'填写虚构账号 → 选择演示分站及成年条件 → 本地注册 → 邀请归因 → 主动购买服务 → 核验和达标。',links:[],fields:{'邀请码':'可选，来自启用的本人站点推广身份；已有会员不能重新绑定。','账号':'虚构账号标识，勿填写真实密码或联系方式。','成年条件':'原型自我确认，非真实认证；生产需要真实鉴权与必要核验。'}},
 home:{purpose:'浏览公开服务、声音、活动、房间及规则，按兴趣找到服务者，再进入咨询或预约。',flow:'选择分类与筛选 → 查看人物、声音和服务 → 核对服务状态 → VIP可咨询 / 匹配 → 普通用户可直接预约购买。',links:[],fields:{'起价':'当前公开已上架服务的最低每期价格。','人数 / 状态':'本地演示在线、接单与房间供给，不表示真实直播流量。','声音':'本地演示音频，可实际播放；后续上传需审核。'}}
};
function mcnHelpMeta(key){const front=key.startsWith('front:'),name=key.replace(/^(front|admin):/,'');if(MCN_HELP[name])return MCN_HELP[name];const newFront={mcn:'mcnGuilds',mcnApply:'mcnGuilds',mcnTeam:'mcnGuilds',mcnDeposit:'mcnDeposits',mcnIncome:'mcnFinance',promotion:'mcnPromotions',promotionIncome:'mcnFinance',invite:'mcnPromotions'};if(newFront[name])return MCN_HELP[newFront[name]];if(front){if(/order|booking|pay|c21Order|c21Product|c21Shop|demandPay/i.test(name))return MCN_HELP.order;if(/earnings|funds|vip|agentEarnings/.test(name))return MCN_HELP.finance;if(/consult|match|room|activit|post|need|message|chat|report/i.test(name))return MCN_HELP.social;if(/provider|offer|studio|services|schedule|apply|agentTeam/i.test(name))return MCN_HELP.service;if(/login|register|recover/.test(name))return MCN_HELP.auth;if(/mine|following|settings|help|agent/.test(name))return MCN_HELP.mine;return MCN_HELP.home;}const g=ROUTE_GROUP[name];return MCN_HELP[({work:'report',service:'service',users:'service',order:'order',fund:'finance',finance:'finance',agents:'site',site:'site',stations:'site',report:'report',config:'config'}[g])]||(/report|overview|Analytics/i.test(name)?MCN_HELP.report:/pay|fund|revenue|withdraw|bill|commission|settle|refund/i.test(name)?MCN_HELP.finance:/order|stop|trial|fulfill/i.test(name)?MCN_HELP.order:/user|provider|product|skill|application|available|review/i.test(name)?MCN_HELP.service:/station|agent|binding/i.test(name)?MCN_HELP.site:/post|reply|board|demand|risk|penalt|appeal|match/i.test(name)?MCN_HELP.social:MCN_HELP.config);}
function mcnHelpButton(key='current'){return `<button type="button" class="mcn-help-button" data-mcn-help="${e(key)}" aria-label="业务与字段说明">业务 / 字段说明</button>`;}
function mcnFieldExplain(label,meta){const all={...MCN_HELP.finance.fields,...MCN_HELP.service.fields,...MCN_HELP.order.fields,...MCN_HELP.mcnPromotions.fields,...meta.fields},hit=Object.keys(all).filter(k=>label.includes(k)).sort((a,b)=>b.length-a.length)[0];if(hit)return all[hit];if(/时间|日期|截止|有效期/.test(label))return '该业务发生、开始、结束或规则有效时间；以本界面标注的业务时区与范围为准。';if(/编号|ID|引用|来源/.test(label))return '连接本记录与原业务对象的唯一编号或演示证据引用，用于到关联模块核对。';if(/比例|分成|百分比/.test(label))return '按对应规则快照的明确分红基数计算，不能对同一资金重复计为收入。';if(/状态|结论|结果/.test(label))return '本对象当前处理阶段，只有满足该阶段、角色及归属的操作才能继续。';if(/原因|说明|备注|依据/.test(label))return '提交人或处理人的情况描述和处理依据，保留在本地记录中供关联模块追溯。';if(/地区|语言|区服|平台|段位|位置|话题|分类/.test(label))return '筛选或适用范围条件；地区、服务范围和当前分类须共同满足才可新增成交。';if(/搜索|筛选/.test(label))return '只影响当前列表显示，清空或重置后恢复允许范围内的记录。';if(/审核|操作|处理/.test(label))return '当前阶段可执行的动作；点击后按表单核对原对象、状态及权限。';if(/账号|会员|用户|买方|购买|服务者/.test(label))return '本业务参与的现有统一账号，按本人、团队或获准本站范围查看。';return '当前界面“'+label+'”所对应的业务信息；结合本页面用途、操作步骤及原关联记录核对。此处只解释页面已公开的字段名称，不展示隐藏私聊或敏感值。';}
function mcnShowHelp(key,button){const frontend=FE.mode!=='admin',name=key==='current'?(frontend?'front:'+FE.page:'admin:'+route):key,meta=mcnHelpMeta(name),context=button?.closest('.modal,.drawer,[role="dialog"],.mcn-surface')||(frontend?document.getElementById('feMain'):document.getElementById('content')),heading=context?.querySelector('h1,h2')?.textContent?.trim()||(frontend?v23Title(FE.page):ROUTE_NAMES[route])||'当前界面',desc=context?.querySelector('.page-heading p,.mcn-lead p,.fe-headcopy p,.fe-auth-heading p')?.textContent?.trim()||'',labels=[...new Set([...context?.querySelectorAll('label>span,label:not(:has(span)),th,dt,.stat-top,.mcn-stats small')||[]].map(el=>{if(el.tagName==='LABEL'){const copy=el.cloneNode(true);copy.querySelectorAll('input,select,textarea,button').forEach(x=>x.remove());return copy.textContent.trim();}return el.textContent.trim();}).filter(t=>t&&t.length<90))].slice(0,55),kind=Object.keys(DETAIL_ROUTE).find(k=>DETAIL_ROUTE[k]===route);if(!frontend&&kind&&FIELD_SCHEMA[kind])for(const f of FIELD_SCHEMA[kind].slice(0,30))if(f.label&&!labels.includes(f.label))labels.push(f.label);const links=frontend?Object.entries(MCN_FRONT).filter(([p])=>p!==FE.page&&p!=='invite').map(([p,v])=>feGoBtn(v[0],p,'','soft small')):meta.links.filter(p=>PAGE[p]&&canRead(p)).map(p=>linkTo(p,ROUTE_NAMES[p]||p));const fields=[...Object.entries(meta.fields||{}),...labels.filter(label=>!Object.hasOwn(meta.fields||{},label)).map(label=>[label,mcnFieldExplain(label,meta)])];const html=`<h3>用途与本界面</h3><p>${e(desc||heading)}</p><p>${e(meta.purpose)}</p><h3>适用角色与入口</h3><p>${e(frontend?'当前用户端账号：'+(feAuthUser()?.name||'游客')+'。从“我的”或当前业务详情进入。':meta.roles||'总站管理员处理获准平台动作，本站站长只查看获准的本人站点记录。')}</p><p>各动作同时核对账号、站点、对象归属和业务状态。预览端切换不授予后台权限。</p><h3>操作步骤与状态变化</h3><p>${e(meta.flow)}</p><h3>业务与字段说明</h3><dl>${fields.map(([name,text])=>`<dt>${e(name)}</dt><dd>${e(text)}</dd>`).join('')}</dl><h3>异常处理</h3><p>根据界面提示处理身份、资格、归属、材料、档期冲突或余额不足后重试。支付或出款结果未知先查询原请求；成功回执不重复确认。保存失败不把当前操作当作已生效。</p><h3>关联模块</h3><div class="mcn-links">${links.join('')||'<span>当前账号、服务发现、订单、设置和使用指引。</span>'}</div><h3>原型与真实系统</h3><p>全部身份、签约、款项及审核仅为当前浏览器本地模拟。真实机构认证、电子合约、支付回调、保证金托管、风控、数据隔离、定时过期和统计任务仍待实施。</p>${name.includes('mcn')||name.includes('promotion')?'<h3>机制参考与本平台约定</h3><p>参考 <a href="https://help.huya.com/167" target="_blank" rel="noopener">虎牙公会分成说明</a>、<a href="https://help.huya.com/161" target="_blank" rel="noopener">虎牙公会创建与保证金说明</a>中的机构、确认分成和保证金机制。本平台仅采用服务业务流程，金额、比例和期限是演示可配置值。</p>':''}`;MCN.help={key:name,focus:button};const root=document.createElement('div');root.id='mcn-help-root';root.className='mcn-help-dialog';root.innerHTML=`<section role="dialog" aria-modal="true" aria-label="${e(heading)} · 业务与字段说明"><header><h2>${e(heading)} · 业务与字段说明</h2><button class="mcn-help-button" data-mcn-help-close>关闭说明</button></header><div class="mcn-help-body">${html}</div></section>`;document.getElementById('mcn-help-root')?.remove();document.body.appendChild(root);root.querySelector('button')?.focus();}
function mcnHelpClose(){document.getElementById('mcn-help-root')?.remove();MCN.help?.focus?.focus?.();MCN.help=null;}
function mcnSyncRecruits(){for(const r of mcnDB().recruits){if(!['已接受 · 待入驻','入驻申请中','待签约'].includes(r.status))continue;const p=db.providers.find(p=>p.uid===r.user),application=db.applications.find(a=>a.uid===r.user&&a.status==='待审核');r.application=application?.id||r.application||'';if(!p){r.status=application?'入驻申请中':'已接受 · 待入驻';continue;}r.provider=p.id;const g=mcnGet('guilds',r.guild);if(g.status!=='正常'||r.to<TODAY){r.status='已结束';continue;}let contract=r.contract&&mcnDB().contracts.find(c=>c.id===r.contract);if(!contract){if(mcnDB().settings.guildRequireVerified&&p.skill!=='已通过'){r.status='入驻申请中';continue;}if(mcnDB().contracts.some(c=>c.provider===p.id&&['已生效','离会待审','待服务者确认','待公会确认'].includes(c.status)&&c.to>=TODAY)){r.status='待签约';r.note='服务者已有签约或待确认邀请，请处理原关系';continue;}contract={id:mcnId('CONTRACT'),guild:g.id,stationId:g.stationId,provider:p.id,user:p.uid,pct:r.pct,from:TODAY,to:r.to,status:'待服务者确认',guildConfirmed:true,providerConfirmed:false,recruit:r.id,agreement:'DEMO-MCN-CONTRACT-1',createdAt:mcnNow(),source:'local'};mcnDB().contracts.push(contract);r.contract=contract.id;}r.status=contract.status==='已生效'?'已签约':contract.status==='已拒绝'?'已结束':'待签约';}}
function mcnRecruitTable(xs,backend=false){return mcnTable(['招募邀请 / 公会','邀请用户','状态 / 入驻申请','拟定合作','操作'],xs.map(r=>{const g=mcnGet('guilds',r.guild),me=feAuthUser();let actions='';if(!backend&&FE.mode!=='admin'&&r.user===me?.id){if(r.status==='待用户确认')actions=mcnBtn('recruitAccept','接受，入驻为服务者',r.id)+mcnBtn('recruitDecline','拒绝邀请',r.id);else if(['已接受 · 待入驻','入驻申请中'].includes(r.status))actions=feGoBtn(r.status==='入驻申请中'?'查看原入驻进度':'提交服务者入驻','apply','','primary small');else if(r.contract)actions=feGoBtn('查看并确认公会签约','mcnTeam','','soft small');}if(backend&&r.application)actions=linkTo('applications','原入驻审核');return[e(r.id)+'<br>'+e(g.name),e(userName(r.user)),mcnTag(r.status,true)+'<br>'+e(r.application||r.note||''),e('毛收益 '+r.pct+'% / 至 '+r.to),actions||'待本人操作'];}));}
/* Apply the user's configurable, optional-entry policy to forms as well as the command layer. */
const mcnApplyPageBefore=mcnApplyPage;mcnApplyPage=function(){let html=mcnApplyPageBefore();if(!mcnDB().settings.guildMaterialsRequired)html=html.replace(/(<input name="(?:company|license)"[^>]*?) required/g,'$1').replace('机构名称（虚构）','机构名称（虚构，可选）').replace('资质材料引用（演示）','资质材料引用（演示，可选）');html=html.replace(/(<(?:input|textarea) name="(?:contact|intro|payee)"[^>]*?) required/g,'$1').replace('业务联系人（虚构）','业务联系人（虚构，可选）').replace('公会介绍</span>','公会介绍（可选）</span>');html=html.replace('由唯一总站管理员审核。',mcnDB().settings.guildApprovalRequired?'由总站管理员审核。':'当前无需平台审核，可直接创建公会。');return html;};
const mcnTeamPageBefore=mcnTeamPage;mcnTeamPage=function(){mcnSyncRecruits();const u=mcnUser(),g=mcnDB().guilds.find(g=>g.manager===u.id&&g.status!=='已关闭');let html=mcnTeamPageBefore();const recruits=mcnDB().recruits.filter(r=>g?r.guild===g.id:r.user===u.id);const section=(g?mcnPanel('直接邀请会员成为服务者',mcnForm('recruit',g.id,mcnField('user','本站普通会员 / 服务者','', 'select',db.users.filter(x=>x.stationId===g.stationId&&x.status==='正常'&&x.id!==u.id).map(x=>[x.id,x.name+' · '+(db.providers.some(p=>p.uid===x.id)?'服务者':'普通会员')]))+mcnField('pct','拟定公会分红比例（%）',g.pct,'number')+mcnField('to','合作截止日期',g.contractDays?mcnDeadline(g.contractDays):'9999-12-31','date'),'发送普通用户招募邀请')):'')+mcnPanel('会员招募进度',mcnRecruitTable(recruits));return html.replace('</section>', '</section>'+section);};
const mcnGuildsBackBefore=mcnGuildsBack;mcnGuildsBack=function(){mcnSyncRecruits();return mcnGuildsBackBefore().replace('</div>\n','</div>\n')+mcnPanel('会员直接招募与原入驻联动',mcnRecruitTable(mcnFiltered(mcnRows('recruits')),true));};
const mcnSettingsFieldsBefore=mcnSettingsFields;mcnSettingsFields=function(){return mcnPanel('公会准入条件（均可关闭）',[['recruitApprovalRequired','普通会员招募入驻需要平台审核（关闭即可本人提交后直接入驻）'],['guildApprovalRequired','公会申请需要平台审核'],['guildMaterialsRequired','公会申请需要机构材料'],['guildRequireVerified','只招募已认证服务者（关闭即可直接邀请普通会员）'],['guildRequireDeposit','要求最低保证金（关闭后可选自愿缴纳）']].map(([k,l])=>mcnField(k,l,mcnDB().settings[k],'checkbox')).join('')+'<p>默认不要求保证金、机构材料和公会准入审核。推广消费门槛设0、关闭身份核验条件可演示无门槛；正向真实收益只来自实际履约或允许的VIP交易。</p>')+mcnSettingsFieldsBefore();};
