function mcnPromotionTerms(s){const window=s.validDays?s.validDays+' 天内':'不限达标期限',period=s.bindingDays?s.bindingDays+' 天':'不限期',conditions=[s.requireAdult?'成年条件':'',s.requireVerified?'平台演示核验':'',s.minSpend>0?'累计确认服务'+(s.sourceVip?'或已付VIP':'')+' D '+s.minSpend:''].filter(Boolean);return (conditions.length?'有效推广要求：'+window+'满足'+conditions.join('、')+'。':'当前无有效推广门槛，新会员归因即有效。')+'归因及分红效期 '+period+'；只有实际确认服务或允许的VIP收入才产生分红。';}
Object.assign(MCN_HELP.mcnGuilds.fields,{'站点范围':'管理员按站点过滤获准记录；站长只显示本人负责分站。过滤不改变记录的原归属。','状态 / 入驻申请':'招募依次为待用户确认、已接受待入驻、入驻申请中、待签约、已签约或已拒绝；关联原入驻申请编号。','状态 / 编号':'当前签约为待确认、已生效、离会待审、已退出、已拒绝或已替换；编号用于核对原关系。'});
MCN_HELP.mcnGuilds.flow='创建公会 → 可选保证金 → 邀请普通会员 / 服务者 → 本人接受并提交入驻 → 按配置直接入驻或原后台审核 → 本人确认分红签约 → 后续新成交分红 → 离会。';

Object.assign(MCN_HELP.mcnFinance.fields,{'已确认应得':'已确认来源中按公会 / 推广比例归集的权益，不是会员消费总额。','可结算':'当前应得减已付和申请占用，且不在等待期、售后保全或待追回状态。','已到账':'原模拟渠道请求成功回执累计，不代表新产生的收入。','状态':'商业收益为待履约、待达标、等待结算、保全、可结算、已结清或待追回；提款为待审核、待执行、在途、未知、失败或已到账。','状态 / 可提':'显示本来源商业收益状态与当前可申请提款的净金额。','类型 / 归属':'公会分红归属签约公会；推广分红归属个人或机构推广身份。','资金类型 / 申请人':'公会收益、推广收益和可退保证金分别申请，按原归属用户和资金性质核对。','基数 × 比例':'公会采用服务者毛收益×公会比例；推广采用总站留存×推广比例；均保存原成交快照。'});
