for(const key of ['pd8Work','opsInbox'])if(PAGE[key]){const previous=PAGE[key];PAGE[key]=()=>previous()+mcnPanel('公会与推广待办',mcnStats([['公会待审核',mcnRows('guilds').filter(g=>g.status==='待审核').length],['商业提款待审核',mcnRows('withdrawals').filter(w=>w.status==='待审核').length],['出款在途 / 未知',mcnRows('withdrawals').filter(w=>['在途','结果未知'].includes(w.status)).length],['保障待受理',mcnRows('claims').filter(c=>c.status==='待受理').length]])+[['mcnGuilds','招募、签约与机构审核'],['mcnFinance','商业提款与原请求查询'],['mcnDeposits','保证金及原售后保障'],['mcnPromotions','会员归因及有效条件']].filter(([page])=>canRead(page)).map(([page,label])=>linkTo(page,label)).join(' · '));}
